import {createCase,simulatePayment,investigate,rehearse,approve,applyRepair,verify,checks,findings,crew,COURSE} from './core.mjs';
import {decisionBrief,outcomeFacts} from './story-model.mjs';
import {briefMarkup,factsMarkup,downloadFacts} from './story-components.mjs';
import {storyChapters} from './story-chapters.mjs';
import {reportStoryHelp,acknowledgeStoryHelp,confirmStoryAccess} from './story-followup.mjs';
import {suggestedStoryUpdate,sendStoryUpdate} from './story-updates.mjs';
import {esc,conversation} from './customer-shared.mjs';
const root=document.querySelector('#story-app');let s,support,role='merchant',started=false,opened=false,error='';
function reset(scenario='match'){s=simulatePayment(createCase(scenario,'STORY-'+crypto.randomUUID().slice(0,8)));support={messages:[],confirmedAt:null,help:false};started=false;opened=false;error='';role=new URLSearchParams(location.search).get('perspective')==='customer'?'customer':'merchant';render();}
function say(role,text){support.messages.push({id:crypto.randomUUID(),role,text,kind:'message',at:new Date().toISOString()});}
function chapterMarkup(){const chapters=storyChapters(s,{started,opened,confirmed:!!support.confirmedAt,help:support.help});return `<section class="story-journey" aria-label="Recovery journey"><div class="story-section-heading"><span class="customer-eyebrow">THE WHOLE STORY</span><h2>Seven moments. One accountable outcome.</h2><p>Each moment unlocks only when the case has evidence for it.</p></div><ol class="story-chapters">${chapters.map(c=>`<li class="${c.status}"><span class="story-chapter-number">${String(c.number).padStart(2,'0')}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.description)}</small></div><span class="story-chapter-state">${c.status==='done'?'Done':c.status==='held'?'On hold':c.status==='needs-check'?'Needs check':c.status==='reopened'?'Open again':c.status==='current'?'Now':'Upcoming'}</span></li>`).join('')}</ol></section>`;}
function followupMarkup(b){if(!started)return '';if(role==='customer'){if(!b.verified&&!support.help)return '';return `<section class="story-followup ${support.help?'needs-help':''}" aria-label="Customer follow-up"><span class="customer-eyebrow">YOUR VOICE MATTERS</span><h3>${support.help?'We’re keeping this open.':'Does the purchase work for you?'}</h3><p>${support.help?'Your merchant can see your report. Add details in the conversation, then try the lesson again after the next update.':'A technical check does not replace your experience. If it is still locked, tell the merchant here.'}</p>${b.verified?`<button id="story-help" ${support.help?'disabled':''}>${support.help?'Help request recorded':'I still need help'}</button>`:''}</section>`;}return support.help?`<section class="story-followup needs-help" aria-label="Customer follow-up"><span class="customer-eyebrow">CUSTOMER FOLLOW-UP / OPEN</span><h3>The customer says it still does not work.</h3><p>Keep the case open. Acknowledge the message, recheck access without another grant, then wait for the customer to try again.</p><div class="customer-actions"><button id="story-ack" ${support.acknowledgedAt?'disabled':''}>${support.acknowledgedAt?'Acknowledged':'Acknowledge customer'}</button><button id="story-recheck" class="primary" ${support.acknowledgedAt?'':'disabled'}>Recheck access only</button></div><small>Rechecking is read-only. A second access grant is not offered.</small></section>`:'';}
function updateMarkup(){if(!started||role!=='merchant')return '';const draft=suggestedStoryUpdate(s,support);if(!draft)return '';const sent=(support.sentUpdates||[]).includes(draft.key);return `<section class="story-update" aria-label="Suggested customer update"><div class="story-update-heading"><span class="story-portrait portrait portrait-1" aria-hidden="true"></span><div><span class="customer-eyebrow">RELAY / SCRIPTED SUGGESTION</span><h3>A clear update for the customer.</h3></div></div><p class="story-update-why">${esc(draft.why)}</p><div class="story-message-preview"><small>CUSTOMER WILL SEE · ${esc(draft.label)}</small><p>${esc(draft.text)}</p></div><div class="customer-actions"><button id="story-send-update" class="primary" ${sent?'disabled':''}>${sent?'Update sent in this story':'Send this update'}</button></div><small>Merchant action required. Local story conversation only; no email is sent.</small></section>`;}
function agentMarkup(){if(!s.review)return '';const comments=findings(s),exchange=s.review.exchange||[];return `<section class="story-council" aria-label="Specialist review"><div class="story-section-heading"><span class="customer-eyebrow">THE SPECIALIST COUNCIL</span><h2>Four perspectives. One decision you control.</h2><p>Scripted demonstration. Each specialist points to the records behind their view; agreement never overrides a failed purchase check.</p></div><div class="story-agent-grid">${crew.map((agent,i)=>`<article class="story-agent"><div class="story-agent-top"><span class="story-portrait portrait portrait-${i}" aria-hidden="true"></span><div><strong>${esc(agent.name)}</strong><small>${esc(agent.role)}</small></div></div><p class="story-agent-hello">“${esc(agent.hello)}”</p><p>${esc(comments[i].summary)}</p><div class="story-evidence">Evidence: ${comments[i].sources.map(esc).join(' · ')}</div><small class="story-agent-caveat">Limit: ${esc(comments[i].unknown)}</small></article>`).join('')}</div><details class="story-council-exchange"><summary>Read their challenge round (${exchange.length} notes)</summary><ol>${exchange.map(entry=>`<li><strong>${esc(crew[entry.agent]?.name||'Specialist')} · ${esc(entry.kind)}</strong><p>${esc(entry.summary)}</p><small>Sources: ${entry.sources.map(esc).join(', ')}</small></li>`).join('')}</ol></details></section>`;}
function resolutionMarkup(b){if(!s.review)return '';const blocked=s.review.outcome==='blocked',verified=b.verified;return `<section class="story-resolution"><div class="story-section-heading"><span class="customer-eyebrow">THE OUTCOME, WITHOUT A LEAP OF FAITH</span><h2>${blocked?'A refusal is a safe outcome.':verified&&support.confirmedAt?'The customer is back in.':verified?'The system says yes. The customer still gets a say.':'A change is not the finish line.'}</h2><p>${blocked?'The order mismatch keeps access locked while the merchant asks for the right reference.':verified?'The technical checks and customer acknowledgement are recorded separately.':'The case stays open until fresh checks agree and the customer can try the purchase.'}</p></div><div class="story-resolution-grid"><div><span>01 / Change</span><strong>${s.writes===1?'One access grant':blocked?'No access grant':'Awaiting approval'}</strong><p>${s.writes===1?'Only this learner’s purchased course entitlement changed. No new charge or refund.':'Payment and access have not been altered by this story.'}</p></div><div><span>02 / Proof</span><strong>${verified?'Three fresh checks passed':s.proof?'Verification incomplete':'Not yet verified'}</strong><p>Payment record, learner/course entitlement, and lesson retrieval each get their own check.</p></div><div><span>03 / Human</span><strong>${support.confirmedAt&&verified?'Customer confirmed':'Waiting for customer'}</strong><p>${support.confirmedAt&&verified?'The customer opened the sample lesson and confirmed it works.':'The merchant can keep the customer informed in the shared conversation.'}</p></div></div></section>`;}
function handoffMarkup(){
 const status=s.review?.outcome==='blocked'?'A safe stop is still a useful merchant decision.':support.confirmedAt?'The customer has confirmed the sample lesson works.':'The merchant can inspect the evidence and keep the customer informed.';
 return `<section class="story-handoff" aria-label="Continue the recovery journey"><span class="customer-eyebrow">NEXT / THE MERCHANT WORKSPACE</span><h2>Take the story into the recovery desk.</h2><p>${status} Explore the working queue, evidence, agent explanations, approval controls, and outcome checks. The browser sample opens Maya’s seeded case; a configured server opens its own case queue.</p><div class="story-handoff-actions"><a class="primary" href="focus.html?from=story">Open the merchant workspace ↗</a><a href="index.html">See the product overview ↗</a></div><small>The guided story and workspace are separate examples; messages and approvals do not transfer between them. Actual customer tracking uses a private case link.</small></section>`;
}
function render(){const b=decisionBrief(s),facts=outcomeFacts(s,support),blocked=s.review?.outcome==='blocked';
root.innerHTML=`<div class="story-toolbar"><div><span class="customer-eyebrow">INTERACTIVE STORY / SAMPLE DATA</span><label style="display:block;margin-top:8px">Choose a story <select id="scenario"><option value="match" ${s.scenario==='match'?'selected':''}>A purchase recovered</option><option value="conflict" ${s.scenario==='conflict'?'selected':''}>A repair correctly refused</option><option value="read-error" ${s.scenario==='read-error'?'selected':''}>Verification needs another check</option></select></label></div><div class="story-tabs" aria-label="Demo perspective"><button data-role="merchant" aria-pressed="${role==='merchant'}">Merchant</button><button data-role="customer" aria-pressed="${role==='customer'}">Customer</button></div><small>Demo controls only. Real customer access stays separate.</small></div>
${!started?`<section class="story-intro"><div><span class="customer-eyebrow">PAYMENT MADE. EXPERIENCE UNFINISHED.</span><h1>The payment succeeded.<br>The customer is still locked out.</h1><blockquote class="story-quote">“I paid yesterday. My course is still locked, and I haven’t heard anything.”</blockquote><p>Illustrative customer scenario. Follow one case from uncertainty to evidence, an approved decision, and a checked outcome.</p><button class="primary" id="start">Follow this recovery →</button></div><div class="story-pair"><div class="story-receipt"><img src="assets/paypal-mark.svg" alt="PayPal" width="28"><small>SAMPLE PAYMENT RECEIPT</small><strong>$128.00 USD · completed</strong><small>${s.scenario==='conflict'?'A completed payment still needs to match the correct order.':'The payment record exists. Access is a separate question.'}</small></div><div class="story-receipt locked"><small>STILLFRAME ACADEMY / DIGITAL COURSE</small><strong>The Light & Story Workshop</strong><p>▤ Your first lesson is locked.</p><small>Payment success alone did not deliver the purchase.</small></div></div></section>`:`<section class="customer-hero"><div class="story-step">${support.confirmedAt?'06 / CUSTOMER CONFIRMATION':b.verified?'05 / CHECKED OUTCOME':blocked?'03 / SAFE REFUSAL':s.approval?'04 / APPROVED CHANGE':s.rehearsal?'03 / MERCHANT DECISION':s.review?'02 / EVIDENCE EXPLAINED':'01 / CUSTOMER WAITING'}</div><h1>${support.confirmedAt?'“It works—thank you.”':blocked?'The safe decision is to stop.':b.verified?'Access checked. Now ask the customer.':role==='customer'?'A purchase you can follow.':'Close the gap. Show the proof.'}</h1><p>${blocked?'This payment belongs to another order. The system refuses an access grant and asks for the matching purchase reference.':support.confirmedAt?'The sample lesson opened, and the customer confirmed success. Two distinct checks, recorded on one case.':'The customer gets updates. The merchant controls the change. The outcome gets its own check.'}</p><span class="status-chip">${role==='merchant'?'Merchant perspective':'Customer perspective'} · browser simulation</span></section>
${chapterMarkup()}<div class="story-layout"><section class="customer-card"><div class="story-view-label">${role==='merchant'?'MERCHANT WORKSPACE · approval stays with you':'CUSTOMER TRACKER · clear updates and a reply path'}</div>${role==='merchant'?`<span class="customer-eyebrow">THE DECISION BRIEF</span><h2>Understand the next step.</h2>${briefMarkup(b)}<details><summary>Inspect the purchase checks</summary>${checks(s).map(c=>`<div class="story-check ${c.ok?'':'bad'}"><strong>${c.ok?'✓':'!'} ${esc(c.label)}</strong><p>${esc(c.detail)}</p></div>`).join('')}</details><div class="customer-actions">${!s.review?'<button class="primary" data-action="investigate">Review the evidence</button>':blocked?'<button class="primary" data-action="request">Request the matching order reference</button>':!s.rehearsal?'<button class="primary" data-action="rehearse">Preview the access change</button>':!s.approval?'<label><input id="approve-check" type="checkbox"> I approve one access grant for this purchase.</label><button class="primary" id="approve" data-action="approve" disabled>Approve this correction</button>':!s.writes?'<button class="primary" data-action="repair">Apply approved correction</button>':!s.proof?'<button class="primary" data-action="verify">Verify payment, access & lesson</button>':s.proof&&!s.proof.passed?'<button class="primary" data-action="verify">Retry verification only</button>':'<button class="primary" data-role="customer">See the customer’s outcome →</button>'}</div>${s.rehearsal?'<div class="story-check"><strong>Exact change</strong><p>Course locked → purchased access active.<br>One learner. One course. Existing payment unchanged.</p></div>':''}`:`<span class="customer-eyebrow">YOUR PURCHASE</span><h2>${esc(COURSE.name)}</h2><p>${b.verified?'The sample access check passed. Open the demo lesson and confirm your experience.':blocked?'The merchant needs the order reference for this purchase. No access change has been made.':'The merchant is reviewing the purchase. You can follow the conversation below.'}</p>${b.verified?`<button class="primary" data-action="open">Open my purchase ↗</button>${opened?'<div class="customer-lesson"><strong>01 / See the light</strong><p>Find a window with soft, indirect daylight. Place an everyday object beside it. Make three frames: facing the light, beside it, and against it.</p><small>Local sample lesson. This story does not retrieve the server’s protected content.</small></div><button data-action="confirm" '+(support.confirmedAt?'disabled':'')+'>It works—thank you</button>':''}`:'<div class="story-check">Course access remains locked.</div>'}<form id="customer-message"><label for="story-message">Ask the merchant a question</label><textarea id="story-message" required maxlength="2000" placeholder="What should I try next?"></textarea><button>Send demo message</button></form>`}<p class="story-error" role="alert">${esc(error)}</p></section><aside><section class="customer-card"><span class="customer-eyebrow">ONE CASE / SHARED CONVERSATION</span><h2>No more silence.</h2><div class="customer-thread">${conversation(support.messages)}</div><p class="story-label">Local story messages only. Nothing is emailed.</p></section><section class="customer-card"><span class="customer-eyebrow">OUTCOME RECEIPT</span><h2>Facts you can inspect.</h2>${factsMarkup(facts)}<button id="download">Download measured facts</button>${support.confirmedAt?'<div class="story-confirm">✓ System verified access<br>✓ Customer confirmed success</div><p class="story-ended">Purchase recovery, with proof and communication.</p><button id="blocked-story">Try the case we refuse →</button>':''}</section></aside></div>${role==='merchant'?agentMarkup():''}${resolutionMarkup()}`}`;
if(started){
 const panel=followupMarkup(b),card=root.querySelector('.story-layout>.customer-card');
 if(panel)card.querySelector('.story-view-label').insertAdjacentHTML('afterend',panel);
 const draftPanel=updateMarkup();if(draftPanel)card.insertAdjacentHTML('beforeend',draftPanel);
 if(support.help){
  const hero=root.querySelector('.customer-hero');hero.querySelector('.story-step').textContent='07 / CUSTOMER FOLLOW-UP';hero.querySelector('h1').textContent='Your request is open again.';
  hero.querySelector('p').textContent='The technical check passed, but the customer reported a problem. The merchant can recheck without applying another grant.';
  hero.querySelector('.status-chip').textContent='Customer needs help · browser simulation';
  const resolution=root.querySelector('.story-resolution');
  if(resolution){resolution.querySelector('h2').textContent='The case stays open for the customer.';resolution.querySelector('.story-resolution-grid>div:last-child strong').textContent='Customer still needs help';}
  if(role==='merchant')card.querySelector('.customer-actions [data-role="customer"]')?.remove();
 }
}
root.querySelector('#story-help')?.addEventListener('click',()=>{reportStoryHelp(support);opened=false;say('customer','I still cannot use my purchase. Please take another look.');render();});
root.querySelector('#story-ack')?.addEventListener('click',()=>{acknowledgeStoryHelp(support);say('merchant','Thanks for telling us. I’m keeping this case open and checking the access again.');render();});
root.querySelector('#story-recheck')?.addEventListener('click',()=>{error='';try{if(!support.help||!support.acknowledgedAt)throw Error('Acknowledge the customer before rechecking.');verify(s);support.recheckedAt=new Date().toISOString();say('automatic',s.proof.passed?'The payment, entitlement, and sample lesson passed another check. Please try opening the lesson again.':'The new check is incomplete. Your case is still open.');}catch(e){error=e.message;}render();});
root.querySelector('#story-send-update')?.addEventListener('click',()=>{error='';try{sendStoryUpdate(s,support,say);}catch(e){error=e.message;}render();});
root.querySelector('#scenario').onchange=e=>reset(e.target.value);root.querySelectorAll('[data-role]').forEach(el=>el.onclick=()=>{role=el.dataset.role;render();});root.querySelector('#start')?.addEventListener('click',()=>{started=true;say('customer','I paid, but my course is still locked. Can you help?');say('merchant','We have your request. We’ll check the payment and course access before making a change.');render();});root.querySelector('#approve-check')?.addEventListener('change',e=>root.querySelector('#approve').disabled=!e.target.checked);root.querySelector('#download')?.addEventListener('click',()=>downloadFacts(facts));root.querySelector('#blocked-story')?.addEventListener('click',()=>reset('conflict'));
root.querySelector('#customer-message')?.addEventListener('submit',e=>{e.preventDefault();const text=e.target.querySelector('textarea').value.trim();if(!text)return;say('customer',text);render();});
root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{error='';try{switch(el.dataset.action){case 'investigate':investigate(s);say('automatic',s.review.outcome==='blocked'?'The payment reference does not match this purchase. Access changes are on hold.':'The sample payment matches. The merchant is reviewing a course access correction.');break;case 'rehearse':rehearse(s);break;case 'approve':if(!root.querySelector('#approve-check').checked)return;approve(s,s.rehearsal.id);break;case 'repair':applyRepair(s);say('automatic','The approved access correction was applied. Verification is still pending.');break;case 'verify':verify(s,{paymentAvailable:s.scenario!=='read-error'||s.reads>0,lessonAvailable:s.scenario!=='read-error'||s.reads>0});say('automatic',s.proof.passed?'The simulated payment, entitlement, and lesson check agree. Please open your purchase.':'The access update was recorded, but verification is incomplete. We are checking again; no repeat grant is needed.');break;case 'open':if(!b.verified)throw Error('Access has not been verified.');opened=true;break;case 'confirm':confirmStoryAccess(s,support,{opened});say('customer','It works—thank you. I can open the lesson now.');break;case 'request':say('merchant','Please provide the order reference from this purchase’s receipt. Do not share passwords or full payment details.');role='customer';break;}}catch(e){error=e.message;}render();});
const thread=root.querySelector('.customer-thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
reset(['match','conflict','read-error'].includes(new URLSearchParams(location.search).get('scenario'))?new URLSearchParams(location.search).get('scenario'):'match');
